import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import { DollarSign, Clock, CheckCircle, TrendingUp } from 'lucide-react';
import dispatchService from '../../services/dispatchService';
import StatusBadge from '../../components/datadisplay/StatusBadge';
import { Package } from 'lucide-react';

const DispatchEarnings = () => {
    const { data, isLoading } = useQuery({
        queryKey: ['dispatch-dashboard'],
        queryFn: dispatchService.getDashboard
    });

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Dispatch Earnings</h1>
                <p className="text-gray-500 mt-1">View your delivery earnings and payouts</p>
            </div>

            {/* Earnings Summary Cards */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border"
                >
                    <div className="flex items-center gap-3 mb-3">
                        <div className="p-2 bg-teal-100 dark:bg-teal-900/30 rounded-lg">
                            <DollarSign className="h-5 w-5 text-teal-600" />
                        </div>
                        <p className="text-sm text-gray-500">Total Earnings</p>
                    </div>
                    <p className="text-2xl font-bold text-gray-900 dark:text-white">
                        ${(data?.totalEarnings || 0).toLocaleString()}
                    </p>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border"
                >
                    <div className="flex items-center gap-3 mb-3">
                        <div className="p-2 bg-amber-100 dark:bg-amber-900/30 rounded-lg">
                            <Clock className="h-5 w-5 text-amber-600" />
                        </div>
                        <p className="text-sm text-gray-500">Pending Payouts</p>
                    </div>
                    <p className="text-2xl font-bold text-gray-900 dark:text-white">
                        ${(data?.pendingEarnings || 0).toLocaleString()}
                    </p>
                </motion.div>

                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.2 }}
                    className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-sm border"
                >
                    <div className="flex items-center gap-3 mb-3">
                        <div className="p-2 bg-emerald-100 dark:bg-emerald-900/30 rounded-lg">
                            <CheckCircle className="h-5 w-5 text-emerald-600" />
                        </div>
                        <p className="text-sm text-gray-500">Paid Out</p>
                    </div>
                    <p className="text-2xl font-bold text-gray-900 dark:text-white">
                        ${(data?.paidEarnings || 0).toLocaleString()}
                    </p>
                </motion.div>
            </div>

            {/* Earnings History */}
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.3 }}
                className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border"
            >
                <div className="p-4 border-b border-gray-200 dark:border-gray-700">
                    <h3 className="font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                        <TrendingUp className="h-5 w-5 text-teal-600" />
                        Earnings History
                    </h3>
                </div>

                {isLoading ? (
                    <div className="p-8 text-center">
                        <div className="w-8 h-8 border-2 border-teal-500 border-t-transparent rounded-full animate-spin mx-auto" />
                    </div>
                ) : (
                    <div className="divide-y divide-gray-200 dark:divide-gray-700">
                        {data?.recentAssignments?.filter(a => a.status === 'delivered').map(assignment => (
                            <div key={assignment.id} className="p-4 hover:bg-gray-50 dark:hover:bg-gray-750 transition-colors">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className="h-10 w-10 rounded-lg bg-gray-100 dark:bg-gray-700 flex items-center justify-center overflow-hidden">
                                            {assignment.productImage ? (
                                                <img src={assignment.productImage} alt={assignment.productName} className="h-full w-full object-cover" />
                                            ) : (
                                                <Package className="h-5 w-5 text-gray-400" />
                                            )}
                                        </div>
                                        <div>
                                            <p className="font-medium text-gray-900 dark:text-white">{assignment.productName}</p>
                                            <p className="text-sm text-gray-500">
                                                {assignment.customerCity}, {assignment.customerState}
                                            </p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className="font-bold text-teal-600">
                                            ${(assignment.deliveryFee * 0.8).toFixed(2)}
                                        </p>
                                        <p className="text-xs text-gray-500">
                                            {new Date(assignment.createdAt).toLocaleDateString()}
                                        </p>
                                    </div>
                                </div>
                            </div>
                        ))}
                        {(!data?.recentAssignments || data.recentAssignments.filter(a => a.status === 'delivered').length === 0) && (
                            <p className="p-8 text-center text-gray-500">No completed deliveries yet</p>
                        )}
                    </div>
                )}
            </motion.div>

            {/* Earnings Info */}
            <div className="bg-teal-50 dark:bg-teal-900/20 border border-teal-200 dark:border-teal-800 rounded-xl p-6">
                <h3 className="font-semibold text-teal-900 dark:text-teal-100 mb-2">How Earnings Work</h3>
                <ul className="space-y-2 text-sm text-teal-800 dark:text-teal-200">
                    <li>• You earn <strong>80%</strong> of the delivery fee for each completed delivery</li>
                    <li>• Earnings are marked as pending until processed for payout</li>
                    <li>• Payouts are processed at the end of each payment cycle</li>
                    <li>• Track your earnings in real-time from this dashboard</li>
                </ul>
            </div>
        </div>
    );
};



export default DispatchEarnings;
